def montar_html() -> str:
    cfg = json.loads(json.dumps(CONFIG))
    for i, look in enumerate(cfg["looks"]):
        look["img"] = "data:image/jpeg;base64," + LOOKS_B64[i]
    for i, style in enumerate(cfg["lab"]):
        if i < len(HAIR_B64):
            style["img"] = "data:image/jpeg;base64," + HAIR_B64[i]
    dados = json.dumps(cfg, ensure_ascii=False).replace("</", "<\\/")
    return (
        TEMPLATE.replace("__PHOTO_SOBRE_B64__", PHOTO_SOBRE_B64)
        .replace("__PHOTO_B64__", PHOTO_B64)
        .replace("__CONFIG_JSON__", dados)
    )


def main() -> None:
    components.html(montar_html(), height=900, scrolling=True)


